functions.open_websocket:
def open_websocket(target: Target, token: str, timeout: float = 60.0):
    websocket = import_websocket()
    try:
        return websocket.create_connection(
            websocket_url(target, token),
            timeout=timeout,
            origin=target.origin,
        )
    except Exception as error:
        # websocket-client exceptions may embed the request URL, which includes
        # the bearer token.  Never propagate their text.
        raise HPCError(
            "WebShell connection failed; the token may have expired or the target is unavailable"
        ) from error

functions.receive_webshell_data:
def receive_webshell_data(ws) -> str:
    raw = ws.recv()
    if not raw:
        return ""
    if isinstance(raw, bytes):
        raw = raw.decode("utf-8", errors="replace")
    try:
        message = json.loads(raw)
    except (json.JSONDecodeError, TypeError) as error:
        raise HPCError("platform returned an invalid WebShell message") from error
    data = message.get("data", "")
    return data if isinstance(data, str) else str(data)
